const params=new URLSearchParams(location.search);if(params.has('journey')||params.has('presentation'))location.replace('lab.html'+location.search+location.hash);try{const r=await fetch('evidence/govuk-bus-pass.json');if(!r.ok)throw Error();const data=await r.json();if(data.outcome==='passed'){document.getElementById('hero-result').textContent='Finish line reached.';document.getElementById('hero-metrics').textContent=data.keyCount+' key events · '+data.steps.length+' evidence frames';const src=data.steps.at(-1)?.screenshot;if(/^evidence\/[a-z0-9-]+\.(jpg|png)$/.test(src))document.getElementById('hero-evidence').src=src;}else{document.getElementById('hero-result').textContent='Inspect the recorded journey.';}}catch{document.getElementById('hero-result').textContent='Follow the keyboard journey.';}